'use strict';
(() => {
const $=s=>document.querySelector(s), E=window.HZLML;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=0)=>Number(v).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d});
const sum=(r,k)=>r.reduce((a,b)=>a+b[k],0), label=m=>new Date(m+'-01T00:00:00Z').toLocaleDateString('en-GB',{month:'short',year:'numeric',timeZone:'UTC'});
const date='2026-10-23';
const pages=[['overview','◈','Executive overview','The commercial picture, in one view.'],['forecast','⌁','Demand & order book','Monthly demand, secured volume and the conversion gap.'],['shipments','⇄','Import & shipments','Inbound volume, arrival timing and cargo evidence.'],['pricing','◇','Premium & pricing','Comparable landed cost and auction preparation.'],['customers','◎','Customer coverage','Total requirement, HZL supply and the addressable gap.'],['exports','↗','Markets & allocation','Balance domestic commitments with export economics.'],['signals','⌘','Market scenarios','Stress-test demand, premium and arrival assumptions.'],['investment','₹','Investment & finance','Project returns, hedge economics, portfolio value and global trends.'],['models','∿','Forecast performance','Evaluate predictive performance before operational use.'],['sources','▦','Data health','Source coverage, reporting periods and freshness.']];
let state={metal:'Zinc',horizon:'rolling',growth:2,shock:0,shift:0,delay:0,domestic:76,capacity:70000,lme:2900,premium:155,fx:84,freight:35,depot:1200,duty:0,auction:160};
let trained=null, imported=null, modelOn=false, importName='', search='', shipmentFilter='All', current='overview';
const accounts=[{id:'A01',name:'Account A',sector:'Galvanization',metal:'Zinc',demand:18000,hzl:11000},{id:'A02',name:'Account B',sector:'Infrastructure',metal:'Zinc',demand:12000,hzl:9000},{id:'A03',name:'Account C',sector:'Automotive',metal:'Zinc',demand:10000,hzl:6500},{id:'A04',name:'Account D',sector:'Steel',metal:'Zinc',demand:16000,hzl:12000},{id:'A05',name:'Account E',sector:'Automotive batteries',metal:'Lead',demand:9000,hzl:5000},{id:'A06',name:'Account F',sector:'Industrial batteries',metal:'Lead',demand:5000,hzl:3500}];
const cargo=[{id:'ZN-01',metal:'Zinc',origin:'South Korea',port:'West coast',tonnes:6400,eta:'2026-11-04',status:'Estimated',evidence:'Cargo declaration pending'},{id:'ZN-02',metal:'Zinc',origin:'Japan',port:'West coast',tonnes:4200,eta:'2026-11-12',status:'Unconfirmed',evidence:'Booking record only'},{id:'ZN-03',metal:'Zinc',origin:'Australia',port:'East coast',tonnes:5100,eta:'2026-11-21',status:'Estimated',evidence:'Carrier milestone pending'},{id:'PB-01',metal:'Lead',origin:'South Korea',port:'West coast',tonnes:2100,eta:'2026-11-08',status:'Estimated',evidence:'Booking record only'},{id:'PB-02',metal:'Lead',origin:'Japan',port:'East coast',tonnes:1500,eta:'2026-11-19',status:'Unconfirmed',evidence:'Cargo declaration pending'}];
const countries={Zinc:[['Vietnam',920,450,510,40,180,75],['Bangladesh',290,20,280,10,190,65],['Indonesia',680,360,350,30,175,80],['UAE',410,120,340,50,170,60]],Lead:[['Vietnam',340,220,140,20,145,70],['Bangladesh',210,90,130,10,155,65],['Indonesia',390,300,120,30,140,80],['UAE',230,140,130,40,150,60]]};
const visibleAccounts=()=>accounts.filter(r=>r.metal===state.metal), visibleCargo=()=>cargo.filter(r=>r.metal===state.metal);
const selectedMonths=()=>state.horizon==='quarter'?['2027-01','2027-02','2027-03']:['2026-11','2026-12','2027-01'];
function forecastRows(){const base=sum(visibleAccounts(),'hzl'),g=trained?.groups[state.metal];return selectedMonths().map((month,i)=>{const offset=E.monthIndex(month)-E.monthIndex('2026-10'),learned=modelOn&&g?.forecasts.find(f=>f.month===month),point=learned?learned.order_tonnes:base*Math.pow(1+state.growth/100,offset);return {month,point:Math.round(point),booked:Math.round(base*[.64,.42,.24][i]),premium:learned?learned.premium_usd_t:state.premium}})}
function card(t,s,b,tag=''){return `<section class="card"><div class="card-head"><div><h2>${esc(t)}</h2><p>${esc(s)}</p></div>${tag?`<span class="tag">${esc(tag)}</span>`:''}</div>${b}</section>`}
const metric=(t,v,u,s)=>`<div class="kpi"><div class="kpi-label">${esc(t)}</div><div class="value">${v} <span class="unit">${esc(u)}</span></div><div class="hint">${esc(s)}</div></div>`;
const table=(h,r)=>`<div class="table-wrap"><table><thead><tr>${h.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${r.length?r.map(a=>`<tr>${a.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${h.length}" class="empty">No matching records.</td></tr>`}</tbody></table></div>`;
const button=(text,action,secondary=false)=>`<button class="${secondary?'secondary':''}" data-action="${action}">${esc(text)}</button>`;
function input(key,title,{min=0,max=1e7,step=1}={}){return `<div class="field"><label for="${key}">${esc(title)}</label><input id="${key}" name="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${state[key]}" required></div>`}
function form(keys,action,text){return `<form data-form="${action}"><div class="form-grid">${keys.join('')}</div><button type="submit">${esc(text)}</button></form>`}
function chart(){const g=modelOn&&trained?.groups[state.metal],base=sum(visibleAccounts(),'hzl'),hist=g?g.rows.slice(-3).map(r=>({month:r.month,point:r.order_tonnes})):['2026-08','2026-09','2026-10'].map((m,i)=>({month:m,point:base*[.94,.97,1][i]})),rows=[...hist,...forecastRows()],max=Math.max(...rows.map(r=>r.point))*1.2,minMonth=E.monthIndex(rows[0].month),span=E.monthIndex(rows.at(-1).month)-minMonth,x=r=>54+(E.monthIndex(r.month)-minMonth)/span*560,y=v=>220-v/max*170;
return `<svg class="chart" viewBox="0 0 650 275" role="img" aria-label="${esc(state.metal)} monthly order volume in tonnes; dashed line shows forward estimates">${[0,.5,1].map(t=>`<line x1="50" x2="625" y1="${y(max*t)}" y2="${y(max*t)}" stroke="#e5ece8"/><text x="3" y="${y(max*t)+4}">${n(max*t/1000)}k</text>`).join('')}<text x="${x(rows[3])}" y="26">OUTLOOK</text><polyline points="${rows.slice(0,3).map(r=>`${x(r)},${y(r.point)}`).join(' ')}" fill="none" stroke="#176c50" stroke-width="3"/><polyline points="${rows.slice(2).map(r=>`${x(r)},${y(r.point)}`).join(' ')}" fill="none" stroke="#176c50" stroke-width="3" stroke-dasharray="7 5"/>${rows.map(r=>`<circle cx="${x(r)}" cy="${y(r.point)}" r="4" fill="#176c50"/><text x="${x(r)}" y="247" text-anchor="middle">${label(r.month).split(' ')[0]}</text><title>${label(r.month)}: ${n(r.point)} tonnes</title>`).join('')}</svg><div class="legend"><span><i class="key"></i>${g?'Imported history':'Illustrative history'}</span><span>┄ ${g?'ML point forecast':'Planning estimate'}</span><span>Tonnes · no probability band</span></div>`}
function allocation(){const cap=state.capacity*(state.metal==='Lead'?.28:1);return `<div class="splitbar"><div style="width:${state.domestic}%"></div><div style="width:${100-state.domestic}%"></div></div><div class="split-labels"><span>Domestic <strong>${state.domestic}%</strong><br>${n(cap*state.domestic/100)} t / month</span><span>Export <strong>${100-state.domestic}%</strong><br>${n(cap*(1-state.domestic/100))} t / month</span></div>`}
function overview(){const f=forecastRows(),a=visibleAccounts(),wallet=100*sum(a,'hzl')/sum(a,'demand'),booked=sum(f,'booked');return `<div class="kpis">${metric('Three-month demand',n(sum(f,'point')/1000,1),'kt',modelOn?'Learned monthly forecast':'Planning estimate')}${metric('Secured order coverage',n(100*booked/sum(f,'point'),1),'%','Booked tonnes ÷ expected orders')}${metric('Customer share of wallet',n(wallet,1),'%','HZL supply ÷ total requirement')}${metric('Inbound pipeline',n(sum(visibleCargo(),'tonnes')/1000,1),'kt','Estimated and unconfirmed cargo')}</div><div class="grid">${card('Demand outlook',`${state.metal} · ${label(f[0].month)}–${label(f.at(-1).month)}`,chart(),modelOn?'ML forecast':'Planning scenario')}${card('Domestic / export plan','Monthly allocation assumption',allocation()+`<div class="rule"></div><p>${n(state.capacity*(state.metal==='Lead'?.28:1))} tonnes available per month</p><button class="link" data-page="exports">Review allocation →</button>`)}</div><div class="grid equal">${card('Monthly commercial plan','Demand and premium on a common planning horizon',table(['Month','Expected orders','Booked','Premium USD/t'],f.map(r=>[label(r.month),n(r.point)+' t',n(r.booked)+' t',n(r.premium,1)])))}${card('Decision agenda','Focused actions for the commercial review',`<div class="signal"><span class="signal-icon">01</span><div><strong>Convert ${n((sum(f,'point')-booked)/1000,1)} kt of open demand</strong><p>Review monthly bookings and the remaining order gap.</p><button class="link" data-page="forecast">Open order book →</button></div></div><div class="signal"><span class="signal-icon">02</span><div><strong>Verify ${visibleCargo().filter(r=>r.status==='Unconfirmed').length} unconfirmed cargo record</strong><p>Confirm metal, quantity and arrival evidence.</p><button class="link" data-page="shipments">Review arrivals →</button></div></div><div class="signal"><span class="signal-icon">03</span><div><strong>Review auction starting premium</strong><p>Compare parity assumptions with comparable offers.</p><button class="link" data-page="pricing">Open pricing →</button></div></div>`)}</div>`}
function demand(){const f=forecastRows();return `<div class="kpis">${metric('Expected orders',n(sum(f,'point')/1000,1),'kt','Selected three-month horizon')}${metric('Booked volume',n(sum(f,'booked')/1000,1),'kt','Illustrative secured order book')}${metric('Remaining conversion',n((sum(f,'point')-sum(f,'booked'))/1000,1),'kt','Expected less booked')}${metric('Forecast basis',modelOn?'Learned':'Scenario','',''+(modelOn?trained.classification:'Monthly run-rate growth'))}</div><div class="grid">${card('Monthly demand trajectory',state.metal+' · tonnes',chart())}${card('Planning assumptions','Applied across the overview and order book',form([input('growth','Monthly growth (%)',{min:-30,max:30,step:.1})],'demand','Apply assumptions')+`<p class="mini">Run rate compounds the selected growth rate. Bookings and capacity remain separate from any aggregate ML forecast.</p><button class="link" data-page="models">Review forecast performance →</button>`)}</div>${card('Order-book detail','Expected orders are estimates, not secured business',table(['Month','Booked t','Expected t','Open opportunity t','Coverage'],f.map(r=>[label(r.month),n(r.booked),n(r.point),n(Math.max(0,r.point-r.booked)),n(100*r.booked/r.point,1)+'%'])))} `}
function shipments(){const a=visibleCargo(),rows=a.filter(r=>shipmentFilter==='All'||r.status===shipmentFilter);return `<div class="kpis">${metric('Inbound volume',n(sum(a,'tonnes')/1000,1),'kt','Selected metal')}${metric('Cargo records',a.length,'','Origin and destination matched')}${metric('Unconfirmed volume',n(sum(a.filter(r=>r.status==='Unconfirmed'),'tonnes')/1000,1),'kt','Cargo verification required')}${metric('Arrival window','November','2026','Estimated dates')}</div>${card('Inbound shipment register','Illustrative cargo records · ETAs are unverified',`<div class="filter-row"><label for="cargo-status">Status</label><select id="cargo-status"><option ${shipmentFilter==='All'?'selected':''}>All</option><option ${shipmentFilter==='Estimated'?'selected':''}>Estimated</option><option ${shipmentFilter==='Unconfirmed'?'selected':''}>Unconfirmed</option></select></div>`+table(['Cargo','Origin','Destination','Tonnes','Arrival','Status'],rows.map(r=>[`<button class="link" data-cargo="${r.id}">${r.id}</button>`,r.origin,r.port,n(r.tonnes),label(r.eta.slice(0,7)).replace('Nov',''+r.eta.slice(-2)+' Nov'),`<span class="tag ${r.status==='Unconfirmed'?'amber':''}">${r.status}</span>`])))}${card('Arrival exposure by origin','Volume in the selected inbound pipeline',a.map(r=>`<div class="bar-row"><span>${r.origin}</span><div class="track"><div class="fill" style="width:${100*r.tonnes/sum(a,'tonnes')}%"></div></div><span>${n(r.tonnes/1000,1)} kt</span></div>`).join(''))}`}
function pricing(){const landedUSD=state.lme+state.premium+state.freight,base=landedUSD*state.fx,tariff=base*state.duty/100,total=base+tariff+state.depot,offers=[['HZL reference',state.premium,state.freight,state.depot/state.fx],['Comparable A',state.premium+15,state.freight+5,state.depot/state.fx+1],['Comparable B',state.premium-8,state.freight+17,state.depot/state.fx+3]];return `<div class="kpis">${metric('Landed parity',n(total),'INR/t','Before recoverable taxes')}${metric('Auction starting premium',n(state.auction),'USD/t','Editable decision input')}${metric('Import premium',n(state.premium),'USD/t','Comparable delivery basis')}${metric('FX assumption',n(state.fx,2),'INR/USD','Applied to USD components')}</div>${card('Import-parity workbench','LME + premium + incremental freight, converted to INR; duty and depot added separately',form([input('lme','LME (USD/t)'),input('premium','Import premium (USD/t)'),input('fx','FX (INR/USD)',{min:.01,step:.01}),input('freight','Incremental freight (USD/t)'),input('depot','Depot cost (INR/t)'),input('duty','Duty (%)',{max:100,step:.1}),input('auction','Auction starting premium (USD/t)')],'pricing','Recalculate parity'))}<div class="grid equal">${card('Landed-cost bridge','Incremental cost components',table(['Component','INR/t'],[['Metal reference',n(state.lme*state.fx)],['Import premium',n(state.premium*state.fx)],['Incremental freight',n(state.freight*state.fx)],['Duty',n(tariff)],['Depot',n(state.depot)],['Total',`<strong>${n(total)}</strong>`]]))}${card('Comparable offer benchmark','Illustrative offers · same grade, delivery, date and credit basis',table(['Offer','Premium','Freight','Depot','Total USD/t'],offers.map(r=>[r[0],n(r[1],1),n(r[2],1),n(r[3],1),n(r[1]+r[2]+r[3],1)]))+`<p class="mini">Exclude freight already included in a quoted premium. Auction clearing remains the price-discovery mechanism.</p>`)}</div>`}
function customerTable(){const rows=visibleAccounts().filter(r=>(r.name+' '+r.sector).toLowerCase().includes(search.toLowerCase()));return table(['Account','Sector','Requirement t/month','HZL supply t/month','Share of wallet','Gap t/month'],rows.map(r=>[r.name,r.sector,n(r.demand),n(r.hzl),n(100*r.hzl/r.demand,1)+'%',n(r.demand-r.hzl)]))}
function customers(){const a=visibleAccounts();return `<div class="kpis">${metric('Total requirement',n(sum(a,'demand')/1000,1),'kt/month','Selected account portfolio')}${metric('HZL supply',n(sum(a,'hzl')/1000,1),'kt/month','Portfolio volume')}${metric('Share of wallet',n(100*sum(a,'hzl')/sum(a,'demand'),1),'%','Volume-weighted coverage')}${metric('Wallet gap',n((sum(a,'demand')-sum(a,'hzl'))/1000,1),'kt/month','Potential scope; conversion not guaranteed')}</div>${card('Customer portfolio','Anonymized illustrative accounts',`<div class="filter-row"><label for="account-search">Find account or sector</label><input type="search" id="account-search" placeholder="Search portfolio" value="${esc(search)}"><button class="secondary" data-action="clear-search">Clear</button></div><div id="account-table">${customerTable()}</div>`)}${card('Sector exposure','Share of total portfolio requirement',a.map(r=>`<div class="bar-row"><span>${r.sector}</span><div class="track"><div class="fill" style="width:${100*r.demand/sum(a,'demand')}%"></div></div><span>${n(100*r.demand/sum(a,'demand'),1)}%</span></div>`).join(''))}`}
function markets(){const rows=countries[state.metal],cap=state.capacity*(state.metal==='Lead'?.28:1),dom=cap*state.domestic/100,required=forecastRows()[0].point;return `<div class="kpis">${metric('Monthly capacity',n(cap/1000,1),'kt','Available planning volume')}${metric('Domestic plan',n(dom/1000,1),'kt',''+state.domestic+'% of capacity')}${metric('Export plan',n((cap-dom)/1000,1),'kt',''+(100-state.domestic)+'% of capacity')}${metric('Domestic coverage',n(100*dom/required,1),'%','Allocated volume ÷ first-month demand')}</div><div class="grid equal">${card('Allocation plan','Scenario allocation; no optimization implied',allocation()+form([input('capacity','Monthly zinc-equivalent capacity (t)',{min:1}),input('domestic','Domestic allocation (%)',{max:100})],'allocation','Apply allocation'))}${card('Demand and capacity alignment','First month in the selected horizon',table(['Measure','Tonnes'],[['Expected domestic orders',n(required)],['Domestic allocation',n(dom)],['Domestic headroom',n(dom-required)],['Export allocation',n(cap-dom)]]))}</div>${card('Export-market screen','Illustrative annual country balances · kt; premium and freight in USD/t',table(['Market','Consumption','Production','Imports','Exports','Net imports','Premium less freight'],rows.map(r=>[r[0],n(r[1]),n(r[2]),n(r[3]),n(r[4]),n(r[3]-r[4]),n(r[5]-r[6])]))+`<p class="mini">Compare product specification, tariffs, delivery costs, credit and market access before committing export volume. Premium less freight excludes conversion and financing costs.</p>`)}`}
function signals(){const f=forecastRows(),stressed=f.map((r,i)=>({...r,point:Math.round(r.point*(1+(i<2?state.shock/100:0))),premium:r.premium+(i<2?state.shift:0)}));return `<div class="kpis">${metric('Baseline orders',n(sum(f,'point')/1000,1),'kt','Selected horizon')}${metric('Stressed orders',n(sum(stressed,'point')/1000,1),'kt','Shock applies to first two months')}${metric('Volume impact',n((sum(stressed,'point')-sum(f,'point'))/1000,1),'kt','Manual sensitivity')}${metric('Arrival delay',state.delay,'days','Applied to indicative cargo ETAs')}</div>${card('Market-event assumptions','User-defined stress test; does not infer event causality',form([input('shock','Domestic / global volume shock (%)',{min:-50,max:50,step:.5}),input('shift','Premium shift (USD/t)',{min:-1000,max:1000}),input('delay','Shipment delay (days)',{max:90})],'signals','Run scenario'))}${card('Monthly scenario impact','Baseline and stressed outcomes',table(['Month','Baseline t','Stressed t','Change t','Stressed premium USD/t'],stressed.map((r,i)=>[label(r.month),n(f[i].point),n(r.point),n(r.point-f[i].point),n(r.premium,1)])))}${card('Arrival sensitivity','Dates move by the selected delay assumption',table(['Cargo','Baseline ETA','Stressed ETA'],visibleCargo().map(r=>{const d=new Date(r.eta+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+state.delay);return [r.id,r.eta,d.toISOString().slice(0,10)]})))}`}
function performance(){const g=trained?.groups[state.metal];return `${card('Forecast workspace','Train aggregate monthly order and premium models',`<div class="actions">${button('Train demonstration model','train')}${button('Download CSV template','template',true)}</div><label class="upload-label" for="history-file">Import approved monthly history · CSV, up to 2 MB</label><input type="file" id="history-file" accept=".csv,text/csv"><p id="import-status" role="status">${esc(importName||'History and fitted models remain in session memory.')}</p>${imported?button('Train imported history','train-import'):''}<details><summary>Data contract and methodology</summary><p>At least 36 consecutive closed monthly observations per metal. Predictors must reflect information available at the forecast origin. Align delayed releases to the month they became available.</p><code>${E.columns.join(', ')}</code><p>Separate standardized ridge models predict monthly orders and premium at horizons 1–6. Chronological tests compare against the same month last year. No calibrated prediction intervals.</p></details>`)}${g?`<div class="kpis">${metric('History',g.rows.length,'months',label(g.rows[0].month)+'–'+label(g.rows.at(-1).month))}${metric('Horizon','1–6','months','Direct model per target and horizon')}${metric('Evaluation','Rolling','','Up to 12 historical origins')}${metric('Release status','Candidate','','Independent validation pending')}</div><div class="context-line">${esc(trained.classification)} · Results describe this dataset only.</div>${card('Demand forecast quality','WAPE: absolute error ÷ actual volume; lower is better',table(['Horizon','Tests','Model WAPE','Seasonal WAPE','Bias'],g.metrics.filter(m=>m.target==='order_tonnes').map(m=>[m.horizon+' month(s)',m.n,n(m.wape,1)+'%',n(m.baselineWape,1)+'%',n(m.bias,1)+'%'])))}${card('Premium forecast quality','USD/t error and directional accuracy; flat band ±USD 5/t',table(['Horizon','Tests','MAE USD/t','Model WAPE','Baseline WAPE','Direction'],g.metrics.filter(m=>m.target==='premium_usd_t').map(m=>[m.horizon+' month(s)',m.n,n(m.mae,1),n(m.wape,1)+'%',n(m.baselineWape,1)+'%',n(m.directionAccuracy,1)+'%'])))}${card('Forward estimates','Monthly aggregate predictions',table(['Month','Order tonnes','Premium USD/t','Direction'],g.forecasts.map(r=>[label(r.month),n(r.order_tonnes),n(r.premium_usd_t,1),r.premiumDirection]))+`<div class="actions">${button(modelOn?'Use planning scenario':'Use learned forecasts','toggle-model')}${button('Export model card','model-card',true)}${button('Clear session model','clear-model',true)}</div>`)}`:`<div class="empty">Train a model to review forecast quality and forward estimates.</div>`}`}
function sources(){return card('Source coverage','Operational data domains and current connection status',table(['Domain','Required evidence','Freshness basis','Connection'],[['Orders & accounts','Bookings, cancellations, monthly demand','ERP / CRM refresh','Not connected'],['Shipment events','Cargo identity, carrier and port milestones','Event timestamp','Not connected'],['Reported trade','Country / product balances','Reporting period and publication date','Not connected'],['Market prices','LME reference, FX, premiums and freight','Quote timestamp and terms','Not connected'],['Structural outlook','ILZSG, Fastmarkets, Wood Mackenzie','Licensed release calendar','Not connected'],['Global financial context','World Bank monthly commodity reference','Sep 2026; released 2 Oct 2026','Bundled public snapshot'],['Bloomberg enterprise data','Licensed API or approved normalized export','Vendor publication timestamp','No direct feed; session import available'],['Forecast history',trained?esc(trained.classification):'Approved monthly CSV','Origin snapshots',trained?'Session model available':'No history loaded']]))+card('Workspace data','Illustrative records for presentation; no live market quotes',`<div class="source-grid"><div><h3>Planning reference</h3><p>23 October 2026</p></div><div><h3>Operating records</h3><p>Illustrative orders, cargo, accounts and country balances</p></div><div><h3>Model data</h3><p>${trained?esc(trained.classification):'Not loaded'} · session only</p></div></div><div class="actions">${button('Download workspace snapshot','snapshot')}${button('Reset planning assumptions','reset',true)}</div>`)}
function investment(){return window.HZLInvestment.render({metal:state.metal,forecast:forecastRows(),refresh:render})}
const renderers={investment,overview,forecast:demand,shipments,pricing,customers,exports:markets,signals,models:performance,sources};
function render(){current=location.hash.slice(1);if(current==='ml')current='models';if(!renderers[current])current='overview';const page=pages.find(p=>p[0]===current);$('#title').textContent=page[2];$('#subtitle').textContent=page[3];$('#crumb').textContent='Commercial intelligence / '+page[2];$('#nav').innerHTML=pages.map(p=>`<a href="#${p[0]}" ${p[0]===current?'aria-current="page" class="active"':''}><span aria-hidden="true">${p[1]}</span>${p[2]}</a>`).join('');$('#view').innerHTML=renderers[current]();$('#dataset-label').textContent=modelOn?'ML FORECAST · '+trained.classification.toUpperCase():'ILLUSTRATIVE DATA';$('.toolbar').hidden=current==='investment'&&window.HZLInvestment.activeTab()!=='hedging';if(current==='investment')$('#dataset-label').textContent=window.HZLInvestment.label();$('footer span:last-child').textContent=current==='investment'?'Public monthly references · financial assumptions and private session imports':'Illustrative operating data · no live feeds connected';$('#metal').value=state.metal;$('#horizon').value=state.horizon;}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
function snapshot(){return {asOf:date,classification:current==='investment'?window.HZLInvestment.label():'Illustrative operating records',investment:current==='investment'?window.HZLInvestment.snapshot():null,metal:state.metal,horizon:selectedMonths(),modelClassification:trained?.classification||null,modelActive:modelOn,settings:state,forecast:forecastRows(),accounts:visibleAccounts(),shipments:visibleCargo()}}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.page){location.hash=target.dataset.page;return}if(target.dataset.cargo){const r=cargo.find(c=>c.id===target.dataset.cargo);$('#detail-title').textContent='Cargo '+r.id;$('#detail-body').innerHTML=table(['Field','Record'],[['Metal',r.metal],['Origin',r.origin],['Destination',r.port],['Quantity',n(r.tonnes)+' tonnes'],['ETA',r.eta],['Evidence',r.evidence],['Classification','Illustrative cargo; no live vessel connection']]);$('#detail').showModal();return}try{switch(target.dataset.action){case 'train':trained=E.train(E.synthetic(),{classification:'Synthetic demonstration',cutoff:date});render();notify('Demonstration model trained.');break;case 'train-import':trained=E.train(imported,{classification:'Imported history — unverified',cutoff:date});modelOn=false;render();notify('History trained. Review performance before use.');break;case 'template':download('HZL-monthly-history-example.csv',E.csv(E.synthetic()),'text/csv;charset=utf-8');break;case 'toggle-model':if(!modelOn&&!selectedMonths().every(m=>trained.groups[state.metal]?.forecasts.some(f=>f.month===m)))throw Error('This model does not cover the selected planning months.');modelOn=!modelOn;location.hash='overview';render();break;case 'model-card':download('HZL-model-card.json',trained);break;case 'clear-model':trained=null;imported=null;importName='';modelOn=false;render();notify('Session history and model cleared.');break;case 'clear-search':search='';render();$('#account-search').focus();break;case 'snapshot':case 'export':download('HZL-'+current+'-snapshot.json',snapshot());notify('Workspace snapshot exported.');break;case 'reset':Object.assign(state,{growth:2,shock:0,shift:0,delay:0,domestic:76,capacity:70000,lme:2900,premium:155,fx:84,freight:35,depot:1200,duty:0,auction:160});render();notify('Planning assumptions reset.');break;}}catch(error){notify(error.message)}});
document.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;const updates={};for(const el of form.querySelectorAll('input')){const value=Number(el.value);if(!Number.isFinite(value)){notify('Enter a finite number.');return}updates[el.name]=value}Object.assign(state,updates);render();notify('Planning assumptions updated.');});
document.addEventListener('input',event=>{if(event.target.id==='account-search'){search=event.target.value;$('#account-table').innerHTML=customerTable()}});
document.addEventListener('change',async event=>{const id=event.target.id;if(id==='metal'||id==='horizon'){state[id]=event.target.value;if(modelOn&&!selectedMonths().every(m=>trained?.groups[state.metal]?.forecasts.some(r=>r.month===m))){modelOn=false;notify('Planning mode selected: model coverage differs.')}render()}if(id==='cargo-status'){shipmentFilter=event.target.value;render()}if(id==='history-file'){imported=null;importName='';const file=event.target.files[0];try{if(!file)return;if(file.size>2000000)throw Error('File exceeds 2 MB.');imported=E.validate(E.parseCSV(await file.text()),date);importName=`${file.name}: ${imported.length} monthly observations validated.`;render()}catch(error){render();$('#import-status').textContent=error.message;$('#import-status').className='error';}}});
$('#close').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#print').addEventListener('click',()=>window.print());window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
})();
